export const AGAPE_LANG_ID = "agape";

export const AGAPE_MONARCH_LANGUAGE = {
  defaultToken: "",
  tokenPostfix: ".agape",
  keywords: [
    "agent", "extend", "pure", "sync", "struct", "enum", "event", "action", "tool",
    "authority", "principal", "policy", "prompt", "instruction", "mem",
    "grants", "read", "write", "spawn", "awake", "sleep", "crash", "on",
    "when", "catch", "case", "if", "else", "while", "break", "return", "retry", "default",
    "verify", "decide", "emit", "endorse", "attest", "perform", "abstain", "defer",
    "find", "where", "select", "from", "match", "origin", "forget",
    "all", "any", "quorum", "independent", "dependent",
    "task", "complete", "fail", "cancel",
    "module", "import", "pub", "interface", "requires", "reversible",
  ],
  contextual: [
    "as", "by", "about", "expires", "of", "confidence", "margin", "conformal", "floor", "readiness", "over", "to",
    "reach", "use", "objective", "acceptance", "scope",
  ],
  typeKeywords: [
    "int", "float", "bool", "text", "null", "array", "event", "action",
    "Credence", "Decision", "Entailment", "Contradiction", "Neutral",
    "Principal", "Rule", "Basis", "Verification", "Pass", "Fail",
    "Event", "Error", "Decided", "Abstained", "Attestation", "FailedAttestation",
    "QueryResult", "Internalized", "Forgotten", "ToolStarted", "ToolResolved",
    "Spawned", "AgentAwake", "SleepEvent", "AgentCrashed",
    "Sent", "Delivered", "Resolved", "Expired", "DeliveryRefused",
    "PromptOpened", "Prompt", "TypeMismatch", "RetryExhausted",
    "FailedVerification", "Violation",
  ],
  literals: ["true", "false", "null", "abstained"],
  operators: ["<-", "->", "|>", "==", "!=", "<=", ">=", "&&", "||", "<", ">", "+=", "=", "+", "-", "*", "/", "!"],
  symbols: /[=><!|+\-*/&]+/,
  tokenizer: {
    root: [
      [/\/\/.*$/, "comment"],
      [/\bprompt\b/, { token: "keyword.prompt", next: "@afterPromptKeyword" }],
      [/\bmd\b(?=\s*")/, "keyword.markdown"],
      [/f"/, { token: "string.quote", next: "@fstring" }],
      [/"/, { token: "string.quote", next: "@string" }],
      [/\b\d+\.\d+\b/, "number.float"],
      [/\b\d+\b/, "number"],
      [/\bself\b/, "variable.language"],
      [/[A-Z][\w]*/, { cases: { "@typeKeywords": "type", "@default": "type.identifier" } }],
      [/[a-z_]\w*/, {
        cases: {
          "@keywords": "keyword",
          "@contextual": "keyword.contextual",
          "@typeKeywords": "type",
          "@literals": "keyword.literal",
          "@default": "identifier",
        },
      }],
      [/@symbols/, { cases: { "@operators": "operator", "@default": "" } }],
      [/[{}()[\]]/, "@brackets"],
      [/[;,.:]/, "delimiter"],
    ],
    string: [
      [/\\[nt"\\]/, "string.escape"],
      [/[^"\\]+/, "string"],
      [/"/, { token: "string.quote", next: "@pop" }],
    ],
    afterPromptKeyword: [
      [/[ \t\r]+/, "white"],
      [/\{/, { token: "delimiter.curly", bracket: "@open", next: "@promptMarkdown" }],
      [/./, { token: "", next: "@pop", goBack: 1 }],
    ],
    fstring: [
      [/\\[nt"\\]/, "string.escape"],
      [/\\\$\{/, "string.escape"],
      [/\$\{/, { token: "delimiter.interpolation", next: "@interpolation" }],
      [/[^"$\\]+/, "string"],
      [/"/, { token: "string.quote", next: "@pop" }],
      [/./, "string"],
    ],
    promptMarkdown: [
      [/^(\s*)(\})(?=\s*(?:[;),\]\}]|$))/, ["white", { token: "delimiter.curly", bracket: "@close", next: "@pop" }]],
      [/\\\$\{/, "string.escape"],
      [/\$\{/, { token: "delimiter.interpolation", next: "@interpolation" }],
      [/^(\s{0,3}```.*$)/, { token: "markup.fenced_code", next: "@promptFence" }],
      [/^(\s{0,3}#{1,6})(\s+.*$)/, ["markup.heading.marker", "markup.heading"]],
      [/^(\s*>)(.*$)/, ["markup.quote.marker", "markup.quote"]],
      [/^(\s*)([-+*]|\d+\.)(\s+)/, ["white", "markup.list.marker", "white"]],
      [/`[^`]*`/, "markup.inlinecode"],
      [/\*\*[^*]+\*\*/, "markup.strong"],
      [/\*[^*\n]+\*/, "markup.emphasis"],
      [/\[[^\]\n]+\]\([^)]+\)/, "markup.link"],
      [/[^$`*_#>\[\]{}\\]+/, "string.markdown"],
      [/[{}]/, "string.markdown"],
      [/./, "string.markdown"],
    ],
    promptFence: [
      [/^(\s{0,3}```.*$)/, { token: "markup.fenced_code", next: "@pop" }],
      [/\\\$\{/, "string.escape"],
      [/\$\{/, { token: "delimiter.interpolation", next: "@interpolation" }],
      [/.*$/, "markup.raw"],
    ],
    interpolation: [
      [/\/\/.*$/, "comment"],
      [/f"/, { token: "string.quote", next: "@fstring" }],
      [/"/, { token: "string.quote", next: "@string" }],
      [/\{/, { token: "delimiter.curly", bracket: "@open", next: "@interpolation" }],
      [/\}/, { token: "delimiter.interpolation", bracket: "@close", next: "@pop" }],
      [/\bmd\b(?=\s*")/, "keyword.markdown"],
      [/\b\d+\.\d+\b/, "number.float"],
      [/\b\d+\b/, "number"],
      [/\bself\b/, "variable.language"],
      [/[A-Z][\w]*/, { cases: { "@typeKeywords": "type", "@default": "type.identifier" } }],
      [/[a-z_]\w*/, {
        cases: {
          "@keywords": "keyword",
          "@contextual": "keyword.contextual",
          "@typeKeywords": "type",
          "@literals": "keyword.literal",
          "@default": "identifier",
        },
      }],
      [/@symbols/, { cases: { "@operators": "operator", "@default": "" } }],
      [/[()[\]]/, "@brackets"],
      [/[;,.:]/, "delimiter"],
    ],
  },
};

